SELECT SUM(CASE WHEN status = 'captured' THEN 1 ELSE 0 END) * 1.0 / SUM(CASE WHEN status IN ('captured', 'failed') THEN 1 ELSE 0 END) FROM payments WHERE method = 'bkash' AND created_at_utc >= TIMESTAMP '2025-08-12 00:00:00' - INTERVAL 6 HOUR AND created_at_utc < TIMESTAMP '2025-08-14 00:00:00' + INTERVAL 18 HOUR
